using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace HdrPilot {
public static class ReFramework {
 public const string Marker="hdlss-reframework.json",Nightly="praydog/REFramework-nightly",Stable="praydog/REFramework";
 // Exact executable stems from praydog/REFramework shared/sdk/GameIdentity.cpp.
 static readonly Dictionary<string,string> Games=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){
 {"re2","RE2"},{"bhd2","RE2"},{"re3","RE3"},{"bhd3","RE3"},{"re4","RE4"},{"bhd4","RE4"},{"re7","RE7"},{"bhd7","RE7"},{"re8","RE8"},{"village","RE8"},{"re9","RE9"},{"devilmaycry5","DMC5"},{"dmc5","DMC5"},{"monsterhunterrise","MHRISE"},{"mhrise","MHRISE"},{"mhrisesunbreakdemo","MHRISE"},{"streetfighter6","SF6"},{"sf6","SF6"},{"dd2","DD2"},{"drdr","DRDR"},{"makaimura_gg_re","GGR"},{"makaimura","GGR"},{"gs456","GS456"},{"kunitsugami","KUNITSU"},{"onimusha2","ONIMUSHA2"},{"monsterhunterwilds","MHWILDS"},{"mhwilds","MHWILDS"},{"monster_hunter_stories_3_twisted_reflection_trial","MHSTORIES3"},{"monster_hunter_stories_3_twisted_reflection","MHSTORIES3"},{"starforce","STARFORCE"},{"megamanstarforce","STARFORCE"},{"mmstarforce","STARFORCE"},{"pragmata","PRAGMATA"},{"onimushawots","ONIMUSHA_WOTS"},{"onimushawots_demo","ONIMUSHA_WOTS"}};
 public static string Identify(Game g){string id;return g!=null&&Games.TryGetValue(Path.GetFileNameWithoutExtension(g.Exe??""),out id)?id:null;}
 public static bool NeedsEdition(Game g){return new[]{"RE2","RE3","RE7"}.Contains(Identify(g));}
 static string L(string s){return Appearance.Localize(s);}
 public static bool Recognized(string path){try{if(!DlssCore.Pe64(path)||new FileInfo(path).Length>80000000)return false;string data=Encoding.ASCII.GetString(File.ReadAllBytes(path));return data.Contains("REFramework")&&data.Contains("re2_framework_log");}catch{return false;}}
 public static string Installed(Game g){string p=DlssCore.Safe(Path.GetDirectoryName(g.Exe),"dinput8.dll");return Recognized(p)?p:null;}
 public sealed class Release {public string Tag,Url,Digest,Asset,Repo;public long Size;}
 public static Release Parse(string json,Game g,bool legacy){string id=Identify(g);if(id==null||legacy&&!NeedsEdition(g))throw new Exception(L("REFramework: game or edition not supported."));string repo=legacy?Stable:Nightly,asset=legacy?(id=="RE2"?"RE2_TDB66.zip":id=="RE3"?"RE3_TDB67.zip":"RE7_TDB49.zip"):"REFramework.zip";var r=Core.Json.Deserialize<Dictionary<string,object>>(json);if(Convert.ToBoolean(r["draft"]))throw new Exception(L("REFramework: invalid release."));var a=((System.Collections.IEnumerable)r["assets"]).Cast<Dictionary<string,object>>().SingleOrDefault(x=>Convert.ToString(x["name"])==asset);if(a==null)throw new Exception(L("REFramework: package for this edition is unavailable."));string tag=Convert.ToString(r["tag_name"]),url=Convert.ToString(a["browser_download_url"]),hash=a.ContainsKey("digest")?Convert.ToString(a["digest"]):"";long size=Convert.ToInt64(a["size"]);if(url!="https://github.com/"+repo+"/releases/download/"+tag+"/"+asset||!(Regex.IsMatch(hash,@"^sha256:[a-fA-F0-9]{64}$")||(legacy&&String.IsNullOrEmpty(hash)))||size<4096||size>80000000)throw new Exception(L("REFramework: invalid release."));return new Release{Repo=repo,Asset=asset,Tag=tag,Url=url,Digest=String.IsNullOrEmpty(hash)?"":hash.Substring(7),Size=size};}
 public static string Extract(string zip,string folder){Directory.CreateDirectory(folder);using(var z=new ZipArchive(File.OpenRead(zip),ZipArchiveMode.Read)){var entries=z.Entries.Where(e=>e.FullName=="dinput8.dll").ToArray();if(entries.Length!=1||entries[0].Length<4096||entries[0].Length>80000000)throw new Exception(L("REFramework: invalid package."));string file=DlssCore.Safe(folder,"dinput8.dll");using(var input=entries[0].Open())using(var output=File.Create(file))input.CopyTo(output);if(!Recognized(file))throw new Exception(L("REFramework: invalid package."));return file;}}
 public static string Fetch(Game g,bool legacy,out Release release){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;using(var web=new DlssCore.DownloadClient()){web.Headers[HttpRequestHeader.UserAgent]="HDLSS";release=Parse(web.DownloadString("https://api.github.com/repos/"+(legacy?Stable:Nightly)+"/releases/latest"),g,legacy);string folder=Path.Combine(Core.Data,"reframework-packages",String.IsNullOrEmpty(release.Digest)?Guid.NewGuid().ToString("N"):release.Digest);Directory.CreateDirectory(folder);string zip=Path.Combine(folder,"package.zip");if(!File.Exists(zip)||DlssCore.Hash(zip)!=release.Digest)web.DownloadFile(release.Url,zip);if(new FileInfo(zip).Length!=release.Size||(!String.IsNullOrEmpty(release.Digest)&&DlssCore.Hash(zip)!=release.Digest))throw new Exception(L("REFramework: download checksum mismatch."));return Extract(zip,folder);}}
 public static DlssPlan Prepare(Game g,string source,Release release,bool legacy){Core.Closed(g);if(g.ProtectedInstall||Identify(g)==null)throw new Exception(L("REFramework: game or edition not supported."));var scan=DlssCore.Inspect(g,true,false);if(scan.Blockers.Count>0)throw new Exception(String.Join("\n",scan.Blockers));if(!Recognized(source))throw new Exception(L("REFramework: invalid package."));string root=scan.Folder,dst=DlssCore.Safe(root,"dinput8.dll"),marker=DlssCore.Safe(root,Marker);if(File.Exists(dst)&&!Recognized(dst))throw new Exception(L("dinput8.dll belongs to another loader. Remove that loader first; no file was overwritten."));var m=File.Exists(marker)?DlssCore.ReadManifest(root,Marker):new DlssManifest{Game=g.Id,Folder=root,BackupRoot="reframework-backups/"+Guid.NewGuid().ToString("N"),PreviousOwner="Before REFramework"};if(m.Files.Any(f=>f.Name!="dinput8.dll"||!File.Exists(dst)||DlssCore.Hash(dst)!=f.After))throw new Exception(L("REFramework file changed outside the app. Review it before updating."));m.Build=legacy?"legacy":"unified";m.Release=release.Tag;var p=new DlssPlan{Folder=root,MarkerName=Marker,MarkerExpected=File.Exists(marker)?DlssCore.Hash(marker):null,Manifest=m,Summary="REFramework · "+Identify(g)+" · "+release.Tag+"\n"+release.Url};p.Changes.Add(new DlssChange{Name="dinput8.dll",Source=source,SourceHash=DlssCore.Hash(source),Expected=File.Exists(dst)?DlssCore.Hash(dst):null});return p;}
 public static DlssPlan Remove(Game g){Core.Closed(g);if(g.ProtectedInstall)throw new Exception(g.Evidence);string root=Path.GetDirectoryName(g.Exe),file=Installed(g);if(file==null)throw new Exception(L("No installed components detected."));var p=new DlssPlan{Folder=root,Uninstall=true,Summary=L("Remove REFramework loader; scripts and settings are preserved.")};p.Changes.Add(new DlssChange{Name="dinput8.dll",Delete=true,Expected=DlssCore.Hash(file)});string marker=DlssCore.Safe(root,Marker);if(File.Exists(marker))p.Changes.Add(new DlssChange{Name=Marker,Delete=true,Expected=DlssCore.Hash(marker)});return p;}
 public static FrameworkElement Panel(Window owner,Game g){var panel=new StackPanel();panel.Children.Add(Dialogs.Text(RenoNr.T("Loader per mod e script RE Engine. Installalo solo quando richiesto dalla mod.","Loader for RE Engine mods and scripts. Install only when required by a mod.","Cargador de mods y scripts RE Engine. Instala solo si la mod lo requiere.","Chargeur de mods et scripts RE Engine. Installez si le mod le demande.","Loader für RE-Engine-Mods und Skripte. Nur bei Bedarf der Mod installieren.","Loader de mods e scripts RE Engine. Instale se a mod exigir."),14));var state=Dialogs.Text("",14);panel.Children.Add(state);var edition=new ComboBox{ItemsSource=new[]{L("Current edition / ray tracing"),L("Legacy edition without ray tracing")},SelectedIndex=NeedsEdition(g)?-1:0,Visibility=NeedsEdition(g)?Visibility.Visible:Visibility.Collapsed,Margin=new Thickness(0,8,0,12)};if(NeedsEdition(g))panel.Children.Add(Dialogs.Text(L("Select the installed game edition before downloading."),14));panel.Children.Add(edition);panel.Children.Add(Dialogs.Text(L("Current games: latest official nightly. Legacy editions: matching stable TDB package."),13));var actions=new StackPanel{HorizontalAlignment=HorizontalAlignment.Left};panel.Children.Add(actions);var info=Dialogs.Text("",14);panel.Children.Add(info);var install=new Button{Content=L("Install / update REFramework"),Margin=new Thickness(0,8,8,8)};var check=new Button{Content=L("Check again"),Margin=new Thickness(0,8,8,8)};var remove=new Button{Content=L("Remove REFramework"),Margin=new Thickness(0,8,8,8),Style=owner.TryFindResource("RestoreAction") as Style};actions.Children.Add(install);actions.Children.Add(remove);actions.Children.Add(check);Action refresh=()=>{bool exists=Installed(g)!=null;state.Text="RE Engine · "+g.Name+" · "+L(exists?"Installed files; verify activation in game.":"Not installed");install.Style=owner.TryFindResource(exists?"Installed":"Primary") as Style;remove.IsEnabled=exists;};Action<bool> run=async apply=>{if(ModCenter.Busy||RenoDxUi.IsBusy||RenoNr.Busy)return;if(edition.SelectedIndex<0){info.Text=L("Select the installed game edition before downloading.");return;}ModCenter.Busy=true;panel.IsEnabled=false;try{Release release=null;bool legacy=edition.SelectedIndex==1;string file=await Task.Run(()=>Fetch(g,legacy,out release));string current=Installed(g);bool same=current!=null&&DlssCore.Hash(current)==DlssCore.Hash(file);info.Text=release.Tag+" · "+L(same?"Up to date":"Update available");if(apply&&!same){ModCenter.Busy=false;await InlineOperation.Apply(g,Prepare(g,file,release,legacy),info,refresh);}}catch(Exception ex){info.Text=L(ex.Message);}finally{ModCenter.Busy=false;panel.IsEnabled=true;refresh();}};install.Click+=(s,e)=>run(true);check.Click+=(s,e)=>run(false);remove.Click+=async(s,e)=>{if(ModCenter.Busy||RenoDxUi.IsBusy||RenoNr.Busy)return;panel.IsEnabled=false;try{await InlineOperation.Apply(g,Remove(g),info,refresh);}catch(Exception ex){info.Text=L(ex.Message);}finally{panel.IsEnabled=true;refresh();}};panel.Children.Add(new Expander{Header=L("Details"),Content=Dialogs.Text(ReShadeGroups.FrameworkHelp,14),Margin=new Thickness(0,12,0,4)});panel.Loaded+=(s,e)=>refresh();refresh();return panel;}
}
}
